(()=>{'use strict';
const prefersReduced=matchMedia('(prefers-reduced-motion:reduce)');const motionOff=()=>prefersReduced.matches||document.body.classList.contains('paused');
// Animate actual text nodes, preserving line breaks, emphasis, and accessible names.
const headingObserver=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('letters-visible');headingObserver.unobserve(e.target)}}),{threshold:.3});
document.querySelectorAll('.section-title h2').forEach(h=>{h.setAttribute('aria-label',h.textContent);let count=0;const walk=node=>{for(const child of [...node.childNodes]){if(child.nodeType===3){const fragment=document.createDocumentFragment();child.textContent.split(/(\s+)/).forEach(word=>{if(/^\s+$/.test(word)){fragment.append(document.createTextNode(word));return}const w=document.createElement('span');w.className='animated-word';w.setAttribute('aria-hidden','true');[...word].forEach(char=>{const span=document.createElement('span');span.className='animated-letter';span.textContent=char;span.style.setProperty('--letter',count++);w.append(span)});fragment.append(w)});child.replaceWith(fragment)}else walk(child)}};walk(h);if(motionOff())h.classList.add('letters-visible');else headingObserver.observe(h)});
// Custom cursor supplements, rather than blocks, native keyboard and touch inputs.
const cursor=document.querySelector('.cursor-label');if(cursor&&matchMedia('(pointer:fine)').matches&&!prefersReduced.matches){let frame=0,px=0,py=0;document.addEventListener('pointermove',e=>{px=e.clientX+3;py=e.clientY+3;if(!frame)frame=requestAnimationFrame(()=>{cursor.style.setProperty('--cursor-x',px+'px');cursor.style.setProperty('--cursor-y',py+'px');frame=0});const t=e.target.closest('a,button');cursor.classList.toggle('pointer-active',!!t);cursor.classList.toggle('show-label',!!t?.closest('.case'));cursor.querySelector('span').textContent=t?.closest('.case')?'Click to open':''},{passive:true});document.addEventListener('pointerleave',()=>cursor.style.visibility='hidden');document.addEventListener('pointerenter',()=>cursor.style.visibility='visible')}
const flower=document.querySelector('.flower');if(flower){flower.addEventListener('click',()=>flower.setAttribute('aria-pressed',String(flower.classList.contains('bloom'))))}
const dialog=document.getElementById('room-dialog');if(!dialog)return;
const data=window.roomData,track=dialog.querySelector('.slide-track'),dots=dialog.querySelector('.sheet-dots'),extra=dialog.querySelector('.sheet-extra');let current=0,slides=[],origin=null,audioContext=null,tones=[],muted=true;
const projectSlides=indices=>indices.map(i=>({title:data.projects[i].title,body:data.projects[i].short,kicker:data.projects[i].category,art:[3,19,22,24,17,12][i],href:`project-${i+1}.html`,link:'Explore project'}));
const groups={learning:{title:'My learning shelf',description:'Education and certifications from my resume.',slides:[{title:'IIIT Vadodara',body:'B.Tech in Information Technology · 2022–2026. Learning through software engineering, applications and practical projects.',kicker:'EDUCATION',art:6,href:'about.html',link:'About me'},{title:'Machine Learning using TensorFlow',body:'Infosys Springboard certification. Exploring the foundations of machine learning and intelligent applications.',kicker:'CERTIFICATION',art:12},{title:'Python for Data Science',body:'Infosys Springboard certification, alongside Python Fundamentals.',kicker:'CERTIFICATION',art:3},{title:'Hackathon Finalist',body:'VNRVJIET Krithathon finalist, as listed in my resume.',kicker:'RECOGNITION',art:1}]},projects:{title:'Projects I’ve built',description:'Explore web, mobile and operational applications. Use the arrows or swipe.',slides:projectSlides([0,1,2,3,4,5])},vision:{title:'My computer vision lab',description:'Image processing, recognition and visual experiments.',slides:projectSlides([4,5])},engineering:{title:'How I build',description:'From understanding the problem to delivering reliable software.',slides:[{title:'Understand the problem',body:'Requirements gathering, stakeholder discussions and clear acceptance criteria help define what the application needs to do.',kicker:'01 / DISCOVER',art:6},{title:'Design the workflow',body:'Translate operational needs into application flows, data-entry fields, validations and report structures.',kicker:'02 / DESIGN',art:19},{title:'Build and integrate',body:'Frontend development, application logic, API integration and collaboration across teams turn the workflow into working software.',kicker:'03 / DEVELOP',art:3},{title:'Test and improve',body:'Cross-check functionality, verify reports, debug issues and improve reliability through feedback.',kicker:'04 / DELIVER',art:22}]},sound:{title:'A little space to focus',description:'A quiet ambient tone for the desk. Sound starts only when you choose Play.',slides:[{title:'Let’s build something useful.',body:'I’m interested in meaningful engineering challenges, scalable applications and thoughtful user experiences.',kicker:'PRASHANTH REDDY ERANGARI',art:24,href:'contact.html',link:'Get in touch'}]}};
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n}
function stopAudio(){tones.forEach(t=>{try{t.stop()}catch{}});tones=[];if(audioContext){audioContext.close().catch(()=>{});audioContext=null}muted=true;const b=document.getElementById('ambient-toggle');if(b){b.textContent='▶ Play ambient tone';b.setAttribute('aria-pressed','false')}}
function updateSlide(){const cards=[...track.children];if(!cards.length)return;const center=track.scrollLeft+track.clientWidth/2;current=cards.reduce((best,c,i)=>Math.abs(c.offsetLeft+c.offsetWidth/2-center)<Math.abs(cards[best].offsetLeft+cards[best].offsetWidth/2-center)?i:best,0);dots.querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-current',String(i===current)));dialog.querySelector('.slide-prev').disabled=current===0;dialog.querySelector('.slide-next').disabled=current===cards.length-1;dialog.querySelector('.slide-status').textContent=`${current+1} / ${cards.length} · ${slides[current].title}`}
function go(i){const c=track.children[i];if(c)track.scrollTo({left:c.offsetLeft-(track.clientWidth-c.offsetWidth)/2,behavior:motionOff()?'instant':'smooth'})}
function openSheet(key,button){const group=groups[key];if(!group)return;origin=button;slides=group.slides;current=0;document.getElementById('sheet-title').textContent=group.title;document.getElementById('sheet-description').textContent=group.description;track.replaceChildren();dots.replaceChildren();extra.replaceChildren();slides.forEach((s,i)=>{const card=el('article','slide-card');const art=el('div','slide-art');const im=el('img');im.src=`assets/room/${s.art}.png`;im.alt='';art.append(im);const body=el('div','slide-body');body.append(el('small','',s.kicker),el('h3','',s.title),el('p','',s.body));if(s.href){const link=el('a','pill',s.link+' ↗');link.href=s.href;body.append(link)}card.append(art,body);track.append(card);const dot=el('button');dot.setAttribute('aria-label',`Show ${s.title}`);dot.onclick=()=>go(i);dots.append(dot)});if(key==='sound'){const b=el('button','','▶ Play ambient tone');b.id='ambient-toggle';b.setAttribute('aria-pressed','false');b.onclick=async()=>{if(!muted){stopAudio();return}try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error();audioContext=new Audio();await audioContext.resume();const gain=audioContext.createGain();gain.gain.value=.015;gain.connect(audioContext.destination);[130.81,196,261.63].forEach(f=>{const o=audioContext.createOscillator();o.frequency.value=f;o.type='sine';o.connect(gain);o.start();tones.push(o)});muted=false;b.textContent='Ⅱ Stop ambient tone';b.setAttribute('aria-pressed','true')}catch{stopAudio();b.textContent='Audio unavailable in this browser'}};extra.append(b)}dialog.showModal();document.body.style.overflow='hidden';button.setAttribute('aria-expanded','true');requestAnimationFrame(()=>{track.scrollLeft=0;go(0);updateSlide()})}
document.querySelectorAll('[data-room]').forEach(b=>{b.setAttribute('aria-expanded','false');b.onclick=()=>openSheet(b.dataset.room,b)});
dialog.querySelector('.sheet-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{stopAudio();document.body.style.overflow='';origin?.setAttribute('aria-expanded','false');origin?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)dialog.close()}});dialog.querySelector('.slide-prev').onclick=()=>go(Math.max(0,current-1));dialog.querySelector('.slide-next').onclick=()=>go(Math.min(slides.length-1,current+1));track.addEventListener('scroll',updateSlide,{passive:true});track.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();go(Math.max(0,Math.min(slides.length-1,current+(e.key==='ArrowRight'?1:-1))))}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio()});
})();
